// @vitest-environment jsdom
import { describe, expect, it } from 'vitest'
import { join } from 'node:path'
import { openZipVfs } from '../helpers/zip-vfs'
import { buildPresentationIndex } from '../helpers/index-parse'
import { loadTheme, parseSlide } from '../../src/renderer/src/lib/pptx/parser'
import { evaluateStep, initiallyHidden } from '../../src/renderer/src/lib/pptx/animations'

/**
 * The animated fixture is generated by scripts/make-fixtures.mjs and is the same
 * file the e2e suite opens, so this test guards the contract between the two.
 */
const fixture = join(process.cwd(), 'tests', 'fixtures', 'deck-animated.pptx')

describe('animated deck', () => {
  it('parses three click steps from the injected timeline', async () => {
    const vfs = openZipVfs(fixture)
    const index = buildPresentationIndex(vfs)!
    const readText = async (p: string): Promise<string | null> => vfs.readText(p)
    const theme = await loadTheme({ readText, themePaths: index.themes })
    const slide = await parseSlide({ deckId: 'aaaaaaaaaaaa', theme, readText, pptxUrl: (id, part) => 'http://pptx.localhost/' + id + '/' + part, slideSize: index.slideSize }, index.slides[0].path, 0)
    vfs.close()

    expect(slide).not.toBeNull()
    expect(slide!.steps).toHaveLength(3)
    // Each step must target a real shape on the slide, or nothing would appear.
    const ids = new Set(slide!.elements.map((el) => el.id))
    for (const step of slide!.steps) {
      for (const effect of step.effects) {
        expect(ids.has(effect.targetId)).toBe(true)
        expect(effect.kind).toBe('enter')
      }
    }
  })

  it('hides the three answers until their step arrives', async () => {
    const vfs = openZipVfs(fixture)
    const index = buildPresentationIndex(vfs)!
    const readText = async (p: string): Promise<string | null> => vfs.readText(p)
    const theme = await loadTheme({ readText, themePaths: index.themes })
    const slide = await parseSlide({ deckId: 'aaaaaaaaaaaa', theme, readText, pptxUrl: (id, part) => 'http://pptx.localhost/' + id + '/' + part, slideSize: index.slideSize }, index.slides[0].path, 0)
    vfs.close()

    const steps = slide!.steps
    expect(initiallyHidden(steps).size).toBe(3)
    expect(evaluateStep(steps, 0).visible.size).toBe(0)
    expect(evaluateStep(steps, 1).visible.size).toBe(1)
    expect(evaluateStep(steps, 2).visible.size).toBe(2)
    expect(evaluateStep(steps, 3).visible.size).toBe(3)
  })
})
